BEGIN TRANSACTION;
CREATE TABLE "attendance_records" ("id" integer primary key autoincrement not null, "session_id" integer not null, "student_id" integer not null, "status" varchar check ("status" in ('HADIR', 'SAKIT', 'IZIN', 'ALPHA')) not null default 'HADIR', "note" varchar, "attachment_path" varchar, "created_at" datetime, "updated_at" datetime, foreign key("session_id") references "attendance_sessions"("id") on delete cascade, foreign key("student_id") references "users"("id") on delete cascade);
CREATE TABLE "attendance_sessions" ("id" integer primary key autoincrement not null, "class_id" integer not null, "date" date not null, "status" varchar check ("status" in ('DRAFT', 'LOCKED')) not null default 'DRAFT', "locked_by_id" integer, "locked_at" datetime, "verification_status" varchar check ("verification_status" in ('BELUM_KONFIRMASI', 'PENDING', 'TERVERIFIKASI')) not null default 'BELUM_KONFIRMASI', "school_hours" varchar not null default '07:30 - 15:30', "room" varchar, "created_at" datetime, "updated_at" datetime, foreign key("class_id") references "classes"("id") on delete cascade, foreign key("locked_by_id") references "users"("id") on delete set null);
CREATE TABLE "audit_logs" ("id" integer primary key autoincrement not null, "user_id" integer, "action" varchar not null, "ip_address" varchar, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete set null);
CREATE TABLE "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE "class_journals" ("id" integer primary key autoincrement not null, "class_id" integer not null, "schedule_id" integer, "date" date not null, "activity" text not null, "notes" text, "verification_status" varchar check ("verification_status" in ('BELUM_KONFIRMASI', 'PENDING', 'TERVERIFIKASI')) not null default 'PENDING', "created_by_id" integer not null, "confirmed_by_id" integer, "confirmed_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("class_id") references "classes"("id") on delete cascade, foreign key("schedule_id") references "schedules"("id") on delete set null, foreign key("created_by_id") references "users"("id") on delete cascade, foreign key("confirmed_by_id") references "users"("id") on delete set null);
CREATE TABLE "classes" ("id" integer primary key autoincrement not null, "name" varchar not null, "advisor_id" integer, "secretary_id" integer, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" varchar not null, "queue" varchar not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE "leave_requests" ("id" integer primary key autoincrement not null, "student_id" integer not null, "submitted_by_id" integer not null, "type" varchar check ("type" in ('SAKIT', 'IZIN', 'DISPENSASI')) not null default 'SAKIT', "start_date" date not null, "end_date" date not null, "recipient" varchar not null default 'Guru Pembimbing Sekolah / Wali Kelas', "reason" text not null, "attachment_path" varchar, "signature" text, "status" varchar check ("status" in ('PENDING', 'APPROVED', 'REJECTED')) not null default 'PENDING', "reviewer_id" integer, "review_note" text, "reviewed_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("student_id") references "users"("id") on delete cascade, foreign key("submitted_by_id") references "users"("id") on delete cascade, foreign key("reviewer_id") references "users"("id") on delete set null);
CREATE TABLE "material_journals" ("id" integer primary key autoincrement not null, "teacher_id" integer not null, "class_id" integer not null, "subject_id" integer not null, "schedule_id" integer, "date" date not null, "topic" varchar not null, "plan" text, "assignment" text, "attachment_path" varchar, "created_at" datetime, "updated_at" datetime, foreign key("teacher_id") references "users"("id") on delete cascade, foreign key("class_id") references "classes"("id") on delete cascade, foreign key("subject_id") references "subjects"("id") on delete cascade, foreign key("schedule_id") references "schedules"("id") on delete set null);
CREATE TABLE "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE "notifications" ("id" integer primary key autoincrement not null, "user_id" integer not null, "type" varchar not null, "title" varchar not null, "body" text not null, "read_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "otp_tokens" ("id" integer primary key autoincrement not null, "user_id" integer not null, "code_hash" varchar not null, "expires_at" datetime, "used_at" datetime, "attempts" integer not null default '0', "sent_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE "personal_access_tokens" ("id" integer primary key autoincrement not null, "tokenable_type" varchar not null, "tokenable_id" integer not null, "name" text not null, "token" varchar not null, "abilities" text, "last_used_at" datetime, "expires_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "schedules" ("id" integer primary key autoincrement not null, "class_id" integer not null, "subject_id" integer not null, "teacher_id" integer not null, "day" varchar not null, "start_time" varchar not null, "end_time" varchar not null, "room" varchar not null default 'Lab. 1', "created_at" datetime, "updated_at" datetime, foreign key("class_id") references "classes"("id") on delete cascade, foreign key("subject_id") references "subjects"("id") on delete cascade, foreign key("teacher_id") references "users"("id") on delete cascade);
CREATE TABLE "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE "subjects" ("id" integer primary key autoincrement not null, "name" varchar not null, "code" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "teacher_classes" ("id" integer primary key autoincrement not null, "teacher_id" integer not null, "class_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("teacher_id") references "users"("id") on delete cascade, foreign key("class_id") references "classes"("id") on delete cascade);
CREATE TABLE "terms" ("id" integer primary key autoincrement not null, "name" varchar not null, "start_date" date not null, "end_date" date not null, "effective_days" integer not null default '108', "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "phone" varchar, "nip_nis" varchar, "role" varchar check ("role" in ('SISWA', 'SEKRETARIS', 'GURU_PENGAJAR', 'GURU_PEMBIMBING')) not null default 'SISWA', "is_active" tinyint(1) not null default '1', "class_id" integer, foreign key("class_id") references "classes"("id") on delete set null);
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE INDEX "failed_jobs_connection_queue_failed_at_index" on "failed_jobs" ("connection", "queue", "failed_at");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE INDEX "personal_access_tokens_tokenable_type_tokenable_id_index" on "personal_access_tokens" ("tokenable_type", "tokenable_id");
CREATE UNIQUE INDEX "personal_access_tokens_token_unique" on "personal_access_tokens" ("token");
CREATE INDEX "personal_access_tokens_expires_at_index" on "personal_access_tokens" ("expires_at");
CREATE UNIQUE INDEX "classes_name_unique" on "classes" ("name");
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE UNIQUE INDEX "teacher_classes_teacher_id_class_id_unique" on "teacher_classes" ("teacher_id", "class_id");
CREATE UNIQUE INDEX "attendance_sessions_class_id_date_unique" on "attendance_sessions" ("class_id", "date");
CREATE UNIQUE INDEX "attendance_records_session_id_student_id_unique" on "attendance_records" ("session_id", "student_id");
DELETE FROM "sqlite_sequence";
COMMIT;
